	"com/globalintelli/ZAE_MMSA/i18n/i18n.properties":'# This is the resource bundle for Service Advisor\n\n#XTIT: Application name\nappTitle=Service Advisor\n\n#YDES: Application description\nappDescription=Service Advisor\n\n#~~~ Master View ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTIT: Master view title with placeholder for the number of items\nmasterTitleCount=Service Requests ({0})\nmasterTitleCount1=Service Request ({0})\n\n#XTOL: Tooltip for the search field\nmasterSearchTooltip=Enter an Service Request number or a part of it.\n\n#XBLI: text for a list with no data\nmasterListNoDataText=No Service Requests are currently available\n\n#XBLI: text for a list with no data with filter or search\nmasterListNoDataWithFilterOrSearchText=No matching Service Requests found\n\n#XSEL: Option to sort the master list by ServiceDocumentDescription\nmasterSort1=Service Request\n\n\n#~~~ Detail View ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTOL: Icon Tab Bar Info\ndetailIconTabBarInfo=Info\n\n#XTOL: Icon Tab Bar Attachments\ndetailIconTabBarAttachments=Attachments\n\n#XTOL: Tooltip text for close column button\ncloseColumn=Close\n\n#XTIT: Save as tile app title\nshareSaveTileAppTitle=Service Advisor - {0}\n\n#XTIT: Send E-Mail subject\nshareSendEmailObjectSubject=<Email subject including object identifier PLEASE REPLACE ACCORDING TO YOUR USE CASE> {0}\n\n#YMSG: Send E-Mail message\nshareSendEmailObjectMessage=<Email body PLEASE REPLACE ACCORDING TO YOUR USE CASE> {0} (id: {1})\\r\\n{2}\n\n#XBUT: Text for the send e-mail button\nsendEmail=Send E-Mail\n\n#XTIT: Title text for the price\npriceTitle=Price\n\n#~~~ Not Found View ~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTIT: Not found view title\nnotFoundTitle=Not Found\n\n#YMSG: The ZAE_I_ServiceRequest_03 not found text is displayed when there is no ZAE_I_ServiceRequest_03 with this id\nnoObjectFoundText=This Service Request is not available\n\n#YMSG: The not found text is displayed when there was an error loading the resource (404 error)\nnotFoundText=The requested resource was not found\n\n#~~~ Not Available View ~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTIT: Master view title\nnotAvailableViewTitle=Service Request\n\n#~~~ Error Handling ~~~~~~~~~~~~~~~~~~~~~~~\n\n#YMSG: Error dialog description\nerrorText=Sorry, a technical error occurred! Please try again later.\n\n\nupcoming=Upcoming\n\npast=Past\n\nvehiclerecords=Vehicle Records\n\npreviousmesauring=Previous Measuring Document\n\nodometer=Odometer Reading\n\nfuelgauge=Fuel Gauge\n\nvehiclecondition=Vehicle Condition\n\nnotes=Notes\n\nservicerequest=Accessories Available\n\nservicevcatalog=Service Catalog\n\nsummary=Summary\n\nworkreq=Work Required\n\npaymentterms=Payment Terms\n\ndeliverydate=Delivery Date\n\nTREE_TABLE_SELECTION=Selection Not Allowed For This Level\n\nmasterFilter1=REQUEST NUMBER\n\nmasterFilter2=VEHICLE NUMBER\n\nmasterFilter3=CUSTOMER NAME\n\nmasterFilterName=Service Request Filter\n\nService=Service\n\nID=ID\n\nInfo=Info\n\nValidFrom=Valid From\n\nValidTo=Valid To\n\nCategorizheavailable=Categorization Schema Not available\n\nWarning1=Could not select the list item with the path\n\nWarning2=because the list encountered an error or had no items\n\nW=W\n\nO=O\n\nC=C\n\nR=R\n\nmasterFilterBarText=masterFilterBarText\n\nWarrantyStatus=Warranty Status\n\nOEMWarrantyStatus=OEM Warranty Status\n\nRecallStatus=Recall Status\n\nContractStatus=Contract Status\n\nNext=Next\n\nAddComplaints=Complaints\n\nAddComplaint=Add Complaint\n\nComplaintCode=Complaint Code\n\nComplaintCodeDescription=Complaint Code Description\n\nActions=Actions\n\nMMSA_B01=Workshop Load\n\nBUTTON_Submit=Submit\n\nBUTTON_Cancel=Cancel\n\nDate=Date:\n\nEnterDate=Enter Date\n\nComplaints=\\u0627\\u0644\\u0634\\u0643\\u0627\\u0648\\u064a\n\nPickNote=Pick-up Note\n\nComplainMaterialDescription = Additional Description\n\nkmsconfirmationmsg=Please verify the Odometer Reading before proceeding further. \\n Previous Reading: {0} \\n Current Reading   : {1}\n',
